// 1. Abstraction via Opaque Pointers (Information Hiding)

// reusable_mod.h
typedef struct Context_Opaque Context;

Context* context_create(size_t size);
void context_execute(Context *ctx, int input);
void context_destroy(Context *ctx);

// reusable_mod.c (Implementation detail hidden from caller)
struct Context_Opaque {
    size_t internal_count;
    void (*logger_fn)(const char*); // Embedded specific routine
    int data[100];
};

// 2. Behavioral Reuse via Function Pointers (Strategy Pattern)

typedef int (*OperationFn)(int a, int b);

// Core function accepts specialized behavior
int calculate_result(int x, int y, OperationFn op) {
    return op(x, y);
}

// Specialized routine
int operation_add(int a, int b) {
    return a + b;
}

// Specialized routine
int operation_mult(int a, int b) {
    return a * b;
}

// Usage: calculate_result(5, 3, operation_add);
